document.addEventListener("DOMContentLoaded",function(){Object.defineProperty(Vue.prototype,"$moment",{value:wu_moment});var a=new Vue({el:"#activity-stream-content",data:{count:0,loading:!0,page:1,queried:[],error:!1,errorMessage:""},mounted(){this.pullQuery()},watch:{queried(e){}},methods:{hasMore(){return this.queried.count>5*this.page},refresh(){this.loading=!0,this.pullQuery()},navigatePrev(){this.page=this.page<=1?1:this.page-1,this.loading=!0,this.pullQuery()},navigateNext(){this.page=this.page+1,this.loading=!0,this.pullQuery()},pullQuery(){let t=this;jQuery.ajax({url:ajaxurl,data:{_ajax_nonce:wu_activity_stream_nonce,action:"wu_fetch_activity",page:this.page},success(e){t.loading=!1,Vue.set(a,"loading",!1),e.success&&Vue.set(a,"queried",e.data)},error(e){t.loading=!1,Vue.set(a,"loading",!1),wu_ajax_error(e)}})},get_color_event(e){}}})});